      hu: ["Hossza körülbelül 270 kilométer.", "A Magas-Atlasz hegységben ered.", "Marrákestől közvetlenül északra halad el.", "Safi városától északra torkollik az óceánba.", "A Haouz-síkság mezőgazdaságának fő éltetője.", "Vízhozama erősen függ a hegyi csapadéktól."],
      ro: ["Lungime de aproximativ 270 de kilometri.", "Izvorăște din Munții Atlasul Înalt.", "Traversează regiunea aflată la nord de Marrakech.", "Se varsă în Oceanul Atlantic în apropiere de Safi.", "Sursă vitală pentru sistemul de irigații din Haouz.", "Regim hidrologic sezonier, cu variații mari de debit."],
      en: ["Total length of approximately 270 km.", "Source located in the High Atlas Mountains.", "Flows directly past the northern outskirts of Marrakech.", "Empties into the Atlantic Ocean near Safi.", "Primary irrigation source for the Haouz Plain.", "Highly seasonal flow dependent on mountain snowmelt."],
      es: ["Río que fluye cerca de Marrakech.", "Situado en el territorio del Reino de Marruecos.", "Desempeña un papel en la identidad local de la región.", "Conocido por su importancia paisajística o cultural.", "Documentado en estudios locales y regionales."],
      pt: ["Rio que corre perto de Marraquexe.", "Localizado no território do Reino de Marrocos.", "Desempenha um papel na identidade local da região.", "Conhecido pela sua importância paisagística ou cultural.", "Documentado em estudos locais e regionais."],
      fr: ["Rivière coulant près de Marrakech.", "Situé sur le territoire du Royaume du Maroc.", "Joue un rôle dans l'identité locale de la région.", "Connu pour son importance paysagère ou culturelle.", "Documenté dans des études locales et régionales."],
